import{_ as i,o as t,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Policy System","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/policy.md","filePath":"architecture/policy.md","lastUpdated":null}'),n={name:"architecture/policy.md"};function s(r,e,c,l,d,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="policy-system" tabindex="-1">Policy System <a class="header-anchor" href="#policy-system" aria-label="Permalink to &quot;Policy System&quot;">​</a></h1><p><strong>Status:</strong> Approved foundation; exact API is deferred<br><strong>Date:</strong> 2026-07-28<br><strong>Beads issue:</strong> <code>archie-core-5d7</code></p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Retry limits, authorization, gates, commands, protected paths, tool availability, and similar rules define or constrain what Archie may do. They need consistent consumption, composition, evidence, and audit without erasing their different domain meanings.</p><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><p><code>internal/policy</code> is an explicitly approved shared application contract. It is not infrastructure and it is not a generic domain that owns every rule.</p><p>The shared policy system owns:</p><ul><li>policy identity, version, scope, and applicability;</li><li>typed evaluation invocation;</li><li>deterministic composition and precedence;</li><li>common evaluation states such as satisfied, violated, indeterminate, and not applicable;</li><li>reasons and evidence;</li><li>evaluation audit records;</li><li>registration, discovery, and lifecycle.</li></ul><p>Each consuming domain owns:</p><ul><li>its policy vocabulary and typed inputs;</li><li>its concrete policy definitions;</li><li>its evaluators;</li><li>the meaning and consequence of an evaluation.</li></ul><p>Access therefore owns principals, resources, actions, and authorization consequences. Task lifecycle owns retry eligibility and exhaustion. Task execution owns gate requirements. Workspace mutation owns protected-path effects. Tool execution owns tool and command constraints.</p><p>These policies use consistent evaluation mechanics without pretending their decisions are semantically interchangeable.</p><h2 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h2><p>Infrastructure MAY load, persist, distribute, and audit external policy representations. It MUST NOT define what Archie allows or assign the meaning of a domain policy result.</p><p>The exact Go API, composition operators, precedence rules, and representation format require a focused policy design pass.</p>',15)])])}const m=i(n,[["render",s]]);export{h as __pageData,m as default};
